package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamNutritionBank1 {
    private const val T = "පෝෂණය, සමබල ආහාරය හා පෝෂණ ඌනතා රෝග"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("මිනිස් සිරුරට දෛනිකව අවශ්‍ය සියලුම පෝෂ්‍ය පදාර්ථ නිසි ප්‍රමාණවලින් සහ අනුපාතවලින් අඩංගු ආහාර වේල හඳුන්වන්නේ කෙසේද?", "සමබල ආහාර වේල", "ප්‍රෝටීන් බහුල ආහාර වේල", "නිර්මාංශ ආහාර වේල", "සම්පූර්ණ ධාන්‍ය ආහාර වේල", "සමබල ආහාර වේලක් මගින් කාබෝහයිඩ්‍රේට්, ප්‍රෝටීන්, ලිපිඩ, විටමින්, ඛනිජ, ජලය හා කෙඳි නිසි ප්‍රමාණයෙන් සිරුරට සැපයේ."),
        q("ශරීරයේ දෛනික ක්‍රියාකාරකම් සඳහා ප්‍රධාන වශයෙන් ශක්තිය සපයන මූලික සාර්ව පෝෂකය කුමක්ද?", "කාබෝහයිඩ්‍රේට්", "විටමින්", "ඛනිජ ලවණ", "ජලය", "කාබෝහයිඩ්‍රේට් සිරුරේ සෛලීය ශ්වසනය සඳහා ග්ලූකෝස් සපයන ප්‍රධාන ශක්ති ප්‍රභවය වේ."),
        q("කාබෝහයිඩ්‍රේට් ග්‍රෑම් 1ක් පූර්ණ ඔක්සිකරණයට ලක්වීමේදී සිරුරට ලැබෙන ආසන්න ශක්ති ප්‍රමාණය කැලරි කීයද?", "කිලෝකැලරි 4ක්", "කිලෝකැලරි 9ක්", "කිලෝකැලරි 2ක්", "කිලෝකැලරි 12ක්", "කාබෝහයිඩ්‍රේට් ග්‍රෑම් 1 කින් ආසන්න වශයෙන් 4 kcal (17 kJ) ශක්තියක් මුදාහැරේ."),
        q("කාබෝහයිඩ්‍රේටවල සරලතම ඒකකය වන මොනොසැකරයිඩයකට නිදසුනක් කුමක්ද?", "ග්ලූකෝස්", "සුක්‍රෝස්", "පිෂ්ඨය", "සෙලියුලෝස්", "ග්ලූකෝස්, ෆෲක්ටෝස් සහ ගැලැක්ටෝස් මොනොසැකරයිඩ හෙවත් තනි සීනි ඒකක වේ."),
        q("උක් ගසෙන් ලබාගන්නා සාමාන්‍ය ගෘහස්ථ සීනිවල ප්‍රධාන වශයෙන් අඩංගු ඩයිසැකරයිඩය කුමක්ද?", "සුක්‍රෝස්", "මෝල්ටෝස්", "ලැක්ටෝස්", "ග්ලයිකොජන්", "සුක්‍රෝස් යනු ග්ලූකෝස් සහ ෆෲක්ටෝස් ඒකක එකතු වී සෑදෙන ඩයිසැකරයිඩයකි."),
        q("ක්ෂීරපායී සතුන්ගේ කිරිවල අඩංගු වන ප්‍රධාන කාබෝහයිඩ්‍රේට වර්ගය කුමක්ද?", "ලැක්ටෝස්", "සුක්‍රෝස්", "ග්ලයිකොජන්", "සෙලියුලෝස්", "කිරිවල අඩංගු ස්වාභාවික සීනි වර්ගය ලැක්ටෝස් වේ."),
        q("ශාකවල අතිරික්ත ආහාර සංචිත කර තබන ප්‍රධාන බහුසැකරයිඩය කුමක්ද?", "පිෂ්ඨය", "ග්ලයිකොජන්", "ලැක්ටෝස්", "ග්ලූකෝස්", "සහල්, තිරිඟු, අල වර්ග ආදියේ ශක්තිය සංචිත වන්නේ පිෂ්ඨය (Starch) ලෙසිනි."),
        q("සත්ත්ව දේහ තුළ අක්මාවේ සහ අස්ථි පේශිවල අතිරික්ත ග්ලූකෝස් සංචිත වන බහුසැකරයිඩ ස්වරූපය කුමක්ද?", "ග්ලයිකොජන්", "පිෂ්ඨය", "සුක්‍රෝස්", "ඉන්සියුලින්", "මිනිසා ඇතුළු සතුන්ගේ අතිරික්ත ග්ලූකෝස් අක්මාවේ හා පේශිවල ග්ලයිකොජන් ලෙස ගබඩා වේ."),
        q("ශාක සෛල බිත්ති තැනීමට දායක වන මිනිසාට ජීර්ණය කළ නොහැකි ආහාරමය තන්තු අඩංගු බහුසැකරයිඩය කුමක්ද?", "සෙලියුලෝස්", "ග්ලයිකොජන්", "මෝල්ටෝස්", "ග්ලූකෝස්", "සෙලියුලෝස් මිනිස් ආහාර ජීර්ණ පද්ධතියේදී නොදිරවන අතර මලබද්ධය වළක්වන කෙඳි ලෙස ක්‍රියා කරයි."),
        q("ශරීරයේ නව පටක වර්ධනයට, සෛල අලුත්වැඩියාවට සහ එන්සයිම නිපදවීමට අත්‍යවශ්‍ය වන සාර්ව පෝෂකය කුමක්ද?", "ප්‍රෝටීන", "කාබෝහයිඩ්‍රේට්", "මේදය", "විටමින් C", "ප්‍රෝටීන ශරීරයේ වර්ධනයට හා ගෙවී ගිය පටක ප්‍රතිස්ථාපනයට අවශ්‍ය ප්‍රධාන කාබනික ද්‍රව්‍යයයි."),
        q("ප්‍රෝටීනවල ව්‍යුහාත්මක හා ක්‍රියාකාරී තැනුම් ඒකකය වන්නේ කුමක්ද?", "ඇමයිනෝ අම්ල", "මේද අම්ල", "ග්ලිසරෝල්", "ග්ලූකෝස්", "ප්‍රෝටීන අණු සෑදී ඇත්තේ පෙප්ටයිඩ බන්ධනවලින් බැඳුණු ඇමයිනෝ අම්ල දාම මගිනි."),
        q("මිනිස් සිරුර තුළ සංස්ලේෂණය කළ නොහැකි, ආහාර මගින්ම ලබාගත යුතු ඇමයිනෝ අම්ල හඳුන්වන්නේ කෙසේද?", "අත්‍යවශ්‍ය ඇමයිනෝ අම්ල", "අනවශ්‍ය ඇමයිනෝ අම්ල", "සරල ඇමයිනෝ අම්ල", "සංතෘප්ත ඇමයිනෝ අම්ල", "වැඩිහිටියෙකුට අත්‍යවශ්‍ය ඇමයිනෝ අම්ල 8ක් හෝ 9ක් ආහාරයෙන් අනිවාර්යයෙන් ලබාගත යුතුය."),
        q("සියලුම අත්‍යවශ්‍ය ඇමයිනෝ අම්ල නිසි අනුපාතයෙන් අඩංගු පළමු පන්තියේ (සම්පූර්ණ) ප්‍රෝටීන් බහුල ආහාරයක් කුමක්ද?", "බිත්තර", "ධාන්‍ය පිටි", "කොස් ඇට", "බතල", "බිත්තර, මස්, මාළු හා කිරි පළමු පන්තියේ සම්පූර්ණ ප්‍රෝටීන් අඩංගු සත්ත්ව ප්‍රභව වේ."),
        q("ශාකමය ප්‍රෝටීන් බහුලව ලබාගත හැකි ප්‍රධාන ආහාර කාණ්ඩය කුමක්ද?", "පියලි ඇට සහ පරිප්පු වර්ග", "අල බතල වර්ග", "තෙල් සහිත බීජ වර්ග", "පලතුරු වර්ග", "සෝයා, කඩල, මුං ඇට, කවුපි සහ පරිප්පු වැනි පියලි ඇට උසස් ශාක ප්‍රෝටීන් ප්‍රභව වේ."),
        q("ප්‍රෝටීන් ග්‍රෑම් 1ක් දහනය වීමෙන් සිරුරට මුදාහැරෙන සාමාන්‍ය ශක්ති ප්‍රමාණය කැලරි කීයද?", "කිලෝකැලරි 4ක්", "කිලෝකැලරි 9ක්", "කිලෝකැලරි 7ක්", "කිලෝකැලරි 15ක්", "ප්‍රෝටීන් ග්‍රෑම් එකකින් ආසන්න වශයෙන් කිලෝකැලරි 4ක ශක්තියක් ලැබේ."),
        q("ශරීරයේ ශක්තිය සංචිත කිරීම, අභ්‍යන්තර අවයව කම්පනවලින් ආරක්ෂා කිරීම හා තාප පරිවරණය සිදුකරන පෝෂකය කුමක්ද?", "ලිපිඩ (මේදය)", "කාබෝහයිඩ්‍රේට්", "විටමින්", "ජලය", "සමේ යටි ස්ථරයේ තැන්පත් වන මේදය තාපය පිටවීම වළක්වා අවයව කම්පනයෙන් ආරක්ෂා කරයි."),
        q("ලිපිඩ අණුවක් ජලවිච්ඡේදනය වූ විට ලැබෙන මූලික සංඝටක දෙක මොනවාද?", "මේද අම්ල සහ ග්ලිසරෝල්", "ඇමයිනෝ අම්ල සහ ග්ලූකෝස්", "ග්ලූකෝස් සහ ෆෲක්ටෝස්", "ඛනිජ ලවණ සහ ජලය", "ට්‍රයිග්ලිසරයිඩ සෑදී ඇත්තේ ග්ලිසරෝල් අණුවකට බැඳුණු මේද අම්ල අණු තුනකිනි."),
        q("මේදය ග්‍රෑම් 1ක් පූර්ණ ලෙස ශරීරය තුළ දහනය වීමේදී මුදාහැරෙන ඉහළ ශක්ති ප්‍රමාණය කැලරි කීයද?", "කිලෝකැලරි 9ක්", "කිලෝකැලරි 4ක්", "කිලෝකැලරි 2ක්", "කිලෝකැලරි 6ක්", "මේදය ඒකක ස්කන්ධයකින් කාබෝහයිඩ්‍රේට් මෙන් දෙගුණයකට වැඩි (9 kcal) ශක්තියක් ලබා දෙයි."),
        q("කාමර උෂ්ණත්වයේදී ද්‍රව තත්ත්වයේ පවතින අසංතෘප්ත මේද අම්ල බහුල ශාකමය තෙල් වර්ගයකට නිදසුනක් කුමක්ද?", "තල තෙල්", "සත්ත්ව මේදය", "බටර්", "ගිතෙල්", "ශාක තෙල් වර්ග (තල තෙල්, ඔලිව් තෙල්, සූරියකාන්ත තෙල්) අසංතෘප්ත මේද අම්ලවලින් පොහොසත්ය."),
        q("රුධිරයේ අහිතකර කොලෙස්ටරෝල් (LDL) මට්ටම ඉහළ නංවන, සත්ත්ව මේදයේ හා පොල්තෙල්වල අඩංගු මේද වර්ගය කුමක්ද?", "සංතෘප්ත මේදය", "බහු අසංතෘප්ත මේදය", "ඔමේගා-3 මේද අම්ල", "ඒක අසංතෘප්ත මේදය", "සංතෘප්ත මේදය අධිකව ගැනීමෙන් ධමනි බිත්තිවල මේදය තැන්පත් වී ධමනි සිහින්වීමේ අවදානම වැඩිවේ."),
        q("මිනිස් සිරුර තුළ මේදයේ දියවන විටමින් කාණ්ඩයට අයත් විටමින් 4 නිවැරදිව දැක්වෙන පිළිතුර කුමක්ද?", "විටමින් A, D, E, K", "විටමින් B, C, D, K", "විටමින් A, B, C, D", "විටමින් B-සංකීර්ණය සහ C", "A, D, E, K යන විටමින් හතර මේදයේ දියවන අතර අක්මාවේ සහ මේද පටකවල තැන්පත් වේ."),
        q("ජලයේ දියවන විටමින් කාණ්ඩයට අයත් වන්නේ පහත සඳහන් කවර විටමින් වර්ගද?", "විටමින් B-සංකීර්ණය සහ විටමින් C", "විටමින් A සහ D", "විටමින් E සහ K", "විටමින් A සහ C", "විටමින් B සහ C ජලයේ දියවන බැවින් අතිරික්ත ප්‍රමාණය මුත්‍ර සමග පහසුවෙන් බැහැර වේ."),
        q("ඇසේ පෙනීම, විශේෂයෙන් අඳුරට හුරුවීම (රාත්‍රී පෙනීම) සහ ශ්ලේෂ්මල පටලවල නිරෝගීභාවය සඳහා අත්‍යවශ්‍ය විටමිනය කුමක්ද?", "විටමින් A (රෙටිනෝල්)", "විටමින් D", "විටමින් B1", "විටමින් C", "විටමින් A ඇසේ දෘෂ්ටිවිතානයේ රොඩොප්සින් වර්ණකය නිපදවීමට අත්‍යවශ්‍ය වේ."),
        q("විටමින් A ඌනතාවය නිසා රාත්‍රී කාලයේදී හෝ මඳ අඳුරේදී පෙනීම දුර්වල වන රෝගී තත්ත්වය කුමක්ද?", "රාත්‍රී අන්ධතාව (Night Blindness)", "ඇසේ සුද", "ග්ලුකෝමා", "දුරදක්නාභාවය", "විටමින් A හිඟ වූ විට මුලින්ම ඇතිවන ලක්ෂණය මඳ අඳුරේදී නොපෙනී යාමයි."),
        q("විටමින් A දරුණු ලෙස ඌන වීමෙන් ඇසේ කෝනියාව වියළී ගොස් සදාකාලික අන්ධභාවයට පත්වන රෝගී තත්ත්වය කුමක්ද?", "සෙරොෆ්තැල්මියාව (Xerophthalmia)", "ස්කර්වි", "කැටරැක්ට්", "ට්‍රැකෝමා", "සෙරොෆ්තැල්මියා තත්ත්වයේදී ඇසේ කඳුළු නිපදවීම අඩු වී කෝනියාව තුවාල වී අන්ධභාවය හටගනී."),
        q("විටමින් A ශරීරය තුළ නිපදවා ගැනීමට ඉවහල් වන බීටා-කැරොටින් බහුලව අඩංගු ශාක ආහාර මොනවාද?", "කහ සහ තැඹිලි පැහැති පලතුරු හා තද කොළ පැහැති පලා", "සුදු පාන් සහ තිරිඟු පිටි", "සුදු සීනි හා රසකැවිලි", "ලුණු දැමූ වියළි මත්ස්‍යයන්", "කැරට්, පැසුණු ගස්ලබු, අඹ, වට්ටක්කා සහ තද කොළ පැහැති පලාවල බීටා කැරොටින් බහුලව ඇත."),
        q("ආහාර මගින් ලබාගන්නා කැල්සියම් සහ පොස්පරස් බඩවැලෙන් අවශෝෂණය කර අස්ථිවල තැන්පත් කිරීමට උපකාරී වන විටමිනය කුමක්ද?", "විටමින් D", "විටමින් A", "විටමින් C", "විටමින් K", "විටමින් D නොමැතිව ආහාරයේ ඇති කැල්සියම් නිසි පරිදි සිරුරට අවශෝෂණය කරගත නොහැක."),
        q("ළමුන් තුළ විටමින් D සහ කැල්සියම් ඌනතාවය නිසා අස්ථි මෘදු වී පාද දුනු හැඩයට වක්‍ර වන රෝගය කුමක්ද?", "රිකට්ස් (Rickets)", "ඔස්ටියෝපොරෝසිස්", "බෙරිබෙරි", "ස්කර්වි", "රිකට්ස් රෝගයේදී බර දරන අස්ථි නිසි ලෙස ඛනිජකරණය නොවී ඇද වී යයි."),
        q("වැඩිහිටියන්ගේ අස්ථිවල කැල්සියම් ඌන වී අස්ථි මෘදු වීම හා වේදනාකාරී වීම හඳුන්වන රෝගී තත්ත්වය කුමක්ද?", "ඔස්ටියෝමලේෂියා (Osteomalacia)", "රිකට්ස්", "පෙලැග්‍රා", "ක්වාෂියෝකර්", "වැඩිහිටියන් තුළ විටමින් D හිඟවීමෙන් අස්ථි මෘදු වන රෝගය ඔස්ටියෝමලේෂියාවයි."),
        q("විටමින් D සිරුර තුළ සංස්ලේෂණය වීම උත්තේජනය කරනු ලබන ස්වාභාවික පරිසර සාධකය කුමක්ද?", "උදෑසන මෘදු හිරු එළිය (UV-B කිරණ)", "පිරිසිදු පානීය ජලය", "රාත්‍රී සිසිල් සුළඟ", "ගස්වලින් ලැබෙන ඔක්සිජන්", "සමේ ඇති කොලෙස්ටරෝල් ව්‍යුත්පන්න හිරු එළියේ ඇති UV කිරණ මගින් විටමින් D බවට පත් වේ."),
        q("ප්‍රබල ප්‍රතිඔක්සිකාරකයක් ලෙස ක්‍රියා කරමින් සෛල පටල ආරක්ෂා කරන සහ සමේ සෞඛ්‍යයට හිතකර මේදයේ දියවන විටමිනය කුමක්ද?", "විටමින් E (ටොකෝෆෙරෝල්)", "විටමින් B12", "විටමින් C", "විටමින් D", "විටමින් E ශරීරයේ නිදහස් මුක්තක මගින් සෛලවලට සිදුවන හානිය වළක්වන ප්‍රබල ප්‍රතිඔක්සිකාරකයකි."),
        q("ශරීරයේ කැපුම් තුවාලයකින් රුධිරය පිටවන විට රුධිරය කැටි ගැසීමේ ක්‍රියාවලියට අත්‍යවශ්‍ය වන විටමිනය කුමක්ද?", "විටමින් K", "විටමින් A", "විටමින් E", "විටමින් B1", "විටමින් K මගින් අක්මාවේ ප්‍රෝත්‍රොම්බින් ඇතුළු රුධිර කැටිගැසීමේ සාධක නිපදවීම සිදු කරයි."),
        q("නිරෝගී මිනිස් බඩවැලේ වාසය කරන හිතකර බැක්ටීරියා මගින් ස්වාභාවිකව සංස්ලේෂණය කරනු ලබන විටමිනය කුමක්ද?", "විටමින් K", "විටමින් C", "විටමින් D", "විටමින් A", "අන්ත්‍රික හිතකර බැක්ටීරියා මගින් මිනිසාට අවශ්‍ය විටමින් K ප්‍රමාණයක් නිපදවනු ලබයි."),
        q("විටමින් B1 (තයමින්) ඌනතාවය නිසා ස්නායු දුර්වල වීම, හෘද ක්‍රියාකාරිත්වය අඩාල වීම හා මාංශපේශී ක්ෂය වීම ඇතිවන රෝගය කුමක්ද?", "බෙරිබෙරි (Beriberi)", "ස්කර්වි", "පෙලැග්‍රා", "රිකට්ස්", "කුඩු ඉවත් කළ සුදු සහල් ප්‍රධාන ආහාරය ලෙස ගැනීමෙන් විටමින් B1 ඌන වී බෙරිබෙරි රෝගය හටගනී."),
        q("විටමින් B2 (රයිබෝෆ්ලේවින්) ඌන වූ විට මුඛයේ කොන් පැළී තුවාල වීම හඳුන්වන්නේ කෙසේද?", "ඇන්ගියුලර් ස්ටොමැටයිටිස්", "ජින්ජිවයිටිස්", "ග්ලුකෝමා", "ටොන්සිලයිටිස්", "මුඛ කොන් පැළීම (Cheilosis / Angular Stomatitis) විටමින් B2 ඌනතාවයේ ප්‍රධාන ලක්ෂණයකි."),
        q("විටමින් B3 (නියැසින්) ඌනතාවය නිසා පාචනය, චර්මදාහය සහ ඩිමෙන්ෂියාව (3D රෝග ලක්ෂණ) ඇතිවන රෝගය කුමක්ද?", "පෙලැග්‍රා (Pellagra)", "ස්කර්වි", "බෙරිබෙරි", "මැරස්මස්", "නියැසින් හිඟ වූ විට පාචනය (Diarrhea), චර්මදාහය (Dermatitis) හා මන්දබුද්ධිකත්වය (Dementia) හටගනී."),
        q("ගර්භනී සමයේ මුල් සතිවලදී කලලයේ ස්නායු නාල ආබාධ (Spina Bifida) වැළැක්වීමට අත්‍යවශ්‍ය වන B කාණ්ඩයේ විටමිනය කුමක්ද?", "ෆෝලික් අම්ලය (විටමින් B9)", "විටමින් B1", "විටමින් C", "විටමින් K", "ගැබිණි මව්වරුන්ට ගැබ් ගැනීමට පෙර සහ මුල් මාසවලදී ෆෝලික් අම්ල පෙති ලබා දෙන්නේ මේ නිසාය."),
        q("රතු රුධිර සෛල පරිණත වීමට සහ ස්නායු පද්ධතියේ ක්‍රියාකාරිත්වයට අත්‍යවශ්‍ය, සත්ත්ව ආහාරවලින් පමණක් ලැබෙන විටමිනය කුමක්ද?", "විටමින් B12 (සයනොකොබලමින්)", "විටමින් C", "විටමින් B1", "විටමින් A", "විටමින් B12 ඌනතාවය නිසා මාරාන්තික රක්තහීනතාවය (Pernicious Anaemia) ඇතිවිය හැක."),
        q("ශරීරයේ කොලැජන් ප්‍රෝටීන සංස්ලේෂණයට, තුවාල සුවවීමට සහ යකඩ අවශෝෂණයට උපකාරී වන ප්‍රබල විටමිනය කුමක්ද?", "විටමින් C (ඇස්කෝබික් අම්ලය)", "විටමින් D", "විටමින් K", "විටමින් B1", "විටමින් C මගින් සම්බන්ධක පටක ශක්තිමත් කර ශරීරයේ ප්‍රතිශක්තිය හා තුවාල සුවවීම වේගවත් කරයි."),
        q("විටමින් C ඌනතාවය නිසා විදුරුමසින් ලේ ගැලීම, දත් බුරුල් වීම හා සම යට ලේ බිංදු මතු වීම සිදුවන රෝගය කුමක්ද?", "ස්කර්වි (Scurvy)", "බෙරිබෙරි", "රිකට්ස්", "ක්වාෂියෝකර්", "ස්කර්වි රෝගයේදී කේශනාලිකා බිත්ති බිඳී විදුරුමසින් හා සම යටින් රුධිරය කාන්දු වේ."),
        q("විටමින් C ඉතා ඉහළ සාන්ද්‍රණයකින් අඩංගු දේශීය නැවුම් පලතුරක් කුමක්ද?", "නෙල්ලි සහ පේර", "ඉදුණු කෙසෙල්", "ඇපල්", "වියළි මිදි", "නෙල්ලි, පේර, දෙහි, දොඩම් වැනි ඇඹුල් පලතුරුවල විටමින් C බහුලව අඩංගු වේ."),
        q("පිසීමේදී තාපයට සහ වාතයට නිරාවරණය වීමෙන් ඉතා පහසුවෙන් විනාශ වී යන විටමිනය කුමක්ද?", "විටමින් C", "විටමින් D", "විටමින් A", "විටමින් K", "විටමින් C තාප සංවේදී බැවින් එළවළු හා පලතුරු අධික ලෙස තැම්බීමේදී එය විනාශ වී යයි."),
        q("රතු රුධිර සෛලවල ඔක්සිජන් පරිවහනය කරන හිමොග්ලොබින් වර්ණකය නිපදවීමට අත්‍යවශ්‍ය වන ඛනිජ ලවණය කුමක්ද?", "යකඩ (Fe)", "කැල්සියම්", "අයඩීන්", "සෝඩියම්", "හිමොග්ලොබින්හි කේන්ද්‍රීය පරමාණුව යකඩ වන අතර ඔක්සිජන් පටක වෙත රැගෙන යන්නේ එයයි."),
        q("ශරීරයේ යකඩ ඌන වීම නිසා හිමොග්ලොබින් මට්ටම පහත වැටී සුදුමැලි වීම හා තෙහෙට්ටුව ඇතිවන රෝගී තත්ත්වය කුමක්ද?", "යකඩ ඌනතා රක්තහීනතාවය (Anaemia)", "ගලගණ්ඩය", "ස්කර්වි", "ඔස්ටියෝපොරෝසිස්", "රක්තහීනතාවයේදී නියපොතු සුදුමැලි වීම, කරකැවිල්ල, මහන්සිය හා හතිය ඇතිවේ."),
        q("ආහාරයේ ඇති යකඩ බඩවැලට වඩාත් කාර්යක්ෂමව අවශෝෂණය කර ගැනීමට උපකාරී වන විටමිනය කුමක්ද?", "විටමින් C", "විටමින් D", "විටමින් A", "විටමින් E", "යකඩ සහිත ආහාර වේලක් සමග දෙහි යුෂ හෝ පලතුරක් ගැනීමෙන් යකඩ අවශෝෂණය කිහිප ගුණයකින් වැඩිවේ."),
        q("ආහාරයේ ඇති යකඩ ශරීරයට අවශෝෂණය වීම අඩාල කරනු ලබන තේ සහ කෝපිවල අඩංගු රසායනික සංයෝගය කුමක්ද?", "ටැනින් සහ කැෆේන්", "ඇස්කෝබික් අම්ලය", "සිට්‍රික් අම්ලය", "ග්ලූකෝස්", "ප්‍රධාන ආහාර වේල ගත් විගස තේ හෝ කෝපි පානය කිරීමෙන් යකඩ අවශෝෂණය අවහිර වේ."),
        q("ශරීරයේ අස්ථි සහ දත්වල ප්‍රධාන තැනුම් සංඝටකය වන සහ පේශි සංකෝචනයට දායක වන ඛනිජ ලවණය කුමක්ද?", "කැල්සියම් (Ca)", "අයඩීන්", "යකඩ", "සල්ෆර්", "සිරුරේ අස්ථි ඛනිජකරණයට හා හෘද පේශි සංකෝචනයට කැල්සියම් අත්‍යවශ්‍ය වේ."),
        q("වැඩිහිටි වියේදී, විශේෂයෙන් ආර්තවහරණය වූ කාන්තාවන්ගේ අස්ථිවල ඝනත්වය අඩුවී අස්ථි බිඳෙනසුලු වන රෝගය කුමක්ද?", "ඔස්ටියෝපොරෝසිස් (Osteoporosis)", "ආතරයිටිස්", "රිකට්ස්", "ස්කර්වි", "කැල්සියම් ඌනතාවය නිසා අස්ථි සිදුරු සහිත වී සුළු වැටීමකදී පවා අස්ථි බිඳී යාම සිදුවේ."),
        q("තයිරොක්සින් හෝමෝනය නිපදවීම සඳහා තයිරොයිඩ් ග්‍රන්ථියට අත්‍යවශ්‍ය වන ක්ෂුද්‍ර ඛනිජ ලවණය කුමක්ද?", "අයඩීන් (I)", "යකඩ", "කැල්සියම්", "පොටෑසියම්", "අයඩීන් ඌන වූ විට තයිරොක්සින් නිපදවීම අඩාල වී තයිරොයිඩ් ග්‍රන්ථිය ඉදිමී යයි."),
        q("ආහාරයේ අයඩීන් ඌනතාවය නිසා බෙල්ල ප්‍රදේශයේ තයිරොයිඩ් ග්‍රන්ථිය විශාල වීමෙන් හටගන්නා රෝගය කුමක්ද?", "ගලගණ්ඩය (Goitre)", "රක්තහීනතාවය", "බෙරිබෙරි", "පෙලැග්‍රා", "අයඩීන් ඌනතාවයේ ප්‍රධාන දෘශ්‍යමාන ලක්ෂණය ගලගණ්ඩයයි."),
        q("ළමා වියේදී අයඩීන් ඌන වීම නිසා ශාරීරික හා මානසික වර්ධනය බාල වී ඇතිවන බරපතළ රෝගී තත්ත්වය කුමක්ද?", "ක්‍රෙටිනිස්මය (Cretinism)", "ක්වාෂියෝකර්", "මැරස්මස්", "රිකට්ස්", "අයඩීන් ඌනතාවය නිසා මොළයේ සෛල නිසි ලෙස නොවැඩීමෙන් බුද්ධි ඌනතා හා මිටිභාවය ඇතිවේ."),
        q("ශ්‍රී ලංකාවේ ජනතාව අතර අයඩීන් ඌනතාවය පිටුදැකීම සඳහා ගෙන ඇති ප්‍රධාන ජාතික ප්‍රතිපත්තිමය පියවර කුමක්ද?", "කැකුළු ලුණු සඳහා අයඩීන් මිශ්‍ර කිරීම අනිවාර්ය කිරීම", "පානීය ජලයට අයඩීන් එකතු කිරීම", "පාන් පිටි සඳහා අයඩීන් මුසු කිරීම", "කිරිපිටිවලට අයඩීන් යෙදීම", "ජාතික මට්ටමින් ලුණු අයඩීකරණය කිරීම මගින් මෙරට ගලගණ්ඩ රෝගය සාර්ථකව පාලනය කර ඇත."),
        q("අයඩීකෘත ලුණු ගබඩා කිරීමේදී සහ ආහාර පිසීමේදී සැලකිලිමත් විය යුතු වැදගත් කරුණ කුමක්ද?", "තදින් පියන වැසූ භාජනයක තැබීම හා ව්‍යංජනය ලිපෙන් බෑ පසු එක් කිරීම", "හිරු එළියට නිරාවරණය කර තැබීම", "ආහාර පිසීමට පෙරම උතුරන තෙලට දැමීම", "විවෘතව තැබීම", "අයඩීන් වාෂ්පශීලී බැවින් තාපයට හා විවෘත වාතයට නිරාවරණය වූ විට වාෂ්ප වී ඉවත් වේ."),
        q("ශරීරයේ සෛල බාහිර තරල පරිමාව හා ස්නායු ආවේග සම්ප්‍රේෂණය පාලනය කරන සාමාන්‍ය ලුණුවල අඩංගු ඛනිජය කුමක්ද?", "සෝඩියම් (Na)", "යකඩ", "අයඩීන්", "කැල්සියම්", "සෝඩියම් මගින් තරල සමතුලිතතාව පවත්වා ගන්නා අතර අධික පරිභෝජනය අධික රුධිර පීඩනයට හේතුවේ."),
        q("දිනකට වැඩිහිටියෙකු පරිභෝජනය කළ යුතු උපරිම ලුණු ප්‍රමාණය ලෝක සෞඛ්‍ය සංවිධානය නිර්දේශ කරන්නේ කොපමණද?", "තේ හැඳි 1ක් (ග්‍රෑම් 5ක් පමණ)", "මේස හැඳි 2ක් (ග්‍රෑම් 30ක්)", "තේ හැඳි භාගයකින් හතරෙන් එකක්", "ග්‍රෑම් 15ක්", "දිනකට ග්‍රෑම් 5කට (සෝඩියම් 2g) වඩා අඩුවෙන් ලුණු පරිභෝජනය කිරීම හෘද සෞඛ්‍යයට හිතකරය."),
        q("සෛල අභ්‍යන්තර තරල පීඩනය හා හෘද පේශිවල විද්‍යුත් ක්‍රියාකාරිත්වය නියාමනය කරන ප්‍රධාන ඛනිජ ලවණය කුමක්ද?", "පොටෑසියම් (K)", "යකඩ", "සල්ෆර්", "ෆ්ලෝරයිඩ්", "කෙසෙල්, තැඹිලි වතුර සහ අර්තාපල්වල පොටෑසියම් බහුලව අඩංගු වේ."),
        q("තුවාල සුවවීම වේගවත් කිරීමට, සිරුරේ ප්‍රතිශක්තිකරණයට සහ රස සංවේදනයට උපකාරී වන අංශුමාත්‍ර ඛනිජය කුමක්ද?", "සින්ක් (Zn - සින්ක්)", "කැල්සියම්", "සෝඩියම්", "පොස්පරස්", "සින්ක් ඌන වූ විට ප්‍රතිශක්තිය දුර්වල වී නිතර ආසාදන ඇතිවීම හා තුවාල සුවවීම ප්‍රමාද වීම සිදුවේ."),
        q("ළමා වියේදී ප්‍රෝටීන් ඌනතාවය ප්‍රධාන වශයෙන් බලපෑමෙන් උදරය නෙරා ඒම (ශෝථය) සහිතව ඇතිවන මන්දපෝෂණ රෝගය කුමක්ද?", "ක්වාෂියෝකර් (Kwashiorkor)", "මැරස්මස්", "රිකට්ස්", "ස්කර්වි", "ක්වාෂියෝකර් රෝගයේදී ඇල්බියුමින් අඩුවීම නිසා පටකවල ජලය පිරීමෙන් බඩ හා පාද ඉදිමීම සිදුවේ."),
        q("ක්වාෂියෝකර් රෝගය වැළඳුණු දරුවෙකුගෙන් දැකිය හැකි සුවිශේෂී බාහිර ලක්ෂණයක් වන්නේ කුමක්ද?", "මුහුණ හා උදරය ඉදිමීම සහ දුර්වර්ණ වූ බිඳෙනසුලු කෙස් කලඹ", "ඉතා කෙට්ටු වූ ඇටසැකිලි පෙනුම", "ඇස් රතු වීම", "දත් නෙරා ඒම", "ප්‍රෝටීන් හිඟවීම නිසා මුහුණ පිරුණු පෙනුමක් (Moon face) සහ හිසකෙස් තඹ පැහැ ගැන්වීම ඇතිවේ."),
        q("ආහාරයේ ශක්තිය (කැලරි) සහ ප්‍රෝටීන් යන දෙකෙහිම පූර්ණ ඌනතාවය නිසා දරුවෙකු අස්ථි මත හමක් පෙරවූ සේ කෙට්ටු වන රෝගය කුමක්ද?", "මැරස්මස් (Marasmus)", "ක්වාෂියෝකර්", "ගලගණ්ඩය", "බෙරිබෙරි", "මැරස්මස් රෝගයේදී චර්මාභ්‍යන්තර මේදය සම්පූර්ණයෙන්ම දියවී දරුවා මහලු අයෙකුගේ මුහුණක පෙනුම ගනී."),
        q("මැරස්මස් රෝගයෙන් පෙළෙන කුඩා දරුවෙකුගේ මුහුණෙහි දැකිය හැකි විශේෂිත ලක්ෂණය කුමක්ද?", "වියපත් වූ වඳුරු මුහුණක පෙනුම", "සඳක් බඳු වටකුරු මුහුණ", "දිව එළියට පැමිණි මුහුණ", "ඉදිමුණු කම්මුල්", "මුහුණේ මේදය ක්ෂය වීම නිසා සම රැළි වැටී වඳුරු මුහුණක් බඳු පෙනුමක් ඇතිවේ."),
        q("ආහාර ජීර්ණ පද්ධතියේ චලනයන් (ක්‍රමාකුංචනය) පහසු කරමින් මලබද්ධය වළක්වන ආහාරමය සංඝටකය කුමක්ද?", "ආහාරමය කෙඳි (තන්තු)", "සංතෘප්ත මේදය", "සරල සීනි", "ප්‍රෝටීන් කුඩු", "කෙඳි මගින් මල ද්‍රව්‍යවල පරිමාව වැඩි කර බඩවැල් මගින් අපද්‍රව්‍ය පහසුවෙන් බැහැර කිරීමට උපකාරී වේ."),
        q("ආහාරමය කෙඳි බහුලව අඩංගු නොවන සකස් කළ ආහාර වර්ගයකට නිදසුනක් කුමක්ද?", "සුදු පාන් සහ පිරිපහදු කළ බේකරි නිෂ්පාදන", "නිවුඩු සහල්", "කොහොබ කොළ සහ මුගුණුවැන්න", "පේර සහ ඇපල්", "පිරිපහදු කළ සුදු පිටිවලින් කෙඳි ඉවත් කර ඇති බැවින් ඒවායේ තන්තු ප්‍රමාණය ඉතා අවමය."),
        q("වැඩිහිටි පුද්ගලයෙකු දිනපතා පානය කළ යුතු අවම පිරිසිදු ජල ප්‍රමාණය ආසන්න වශයෙන් කොපමණද?", "ලීටර් 2.0 සිට 2.5 දක්වා (වීදුරු 8-10)", "ලීටර් 0.5ක් පමණ", "ලීටර් 6.0කට වඩා වැඩි", "මිලිලීටර් 500ක්", "දෛනික පරිවෘත්තීය හා බහිස්ස්‍රාවී ක්‍රියා සඳහා දිනකට ජලය ලීටර් 2-2.5ක් පමණ පානය කළ යුතුය."),
        q("ශරීරයේ උෂ්ණත්වය නියතව පවත්වා ගැනීමට සහ අපද්‍රව්‍ය බැහැර කිරීමට ඉවහල් වන ප්‍රධාන අකාබනික මාධ්‍යය කුමක්ද?", "ජලය", "ග්ලූකෝස්", "යකඩ", "කොලෙස්ටරෝල්", "ජලයේ ඇති ඉහළ විශිෂ්ට තාප ධාරිතාව නිසා සිරුරේ උෂ්ණත්වය එකවර වෙනස් නොවී සමතුලිතව පවතී."),
        q("ජාතික ආහාර මාර්ගෝපදේශ අනුව ආහාර පිරමිඩයේ පාදමේ (පදනමේ) පිහිටා ඇති බහුලවම ආහාරයට ගත යුතු කාණ්ඩය කුමක්ද?", "ධාන්‍ය, පිෂ්ඨමය ආහාර සහ අල බතල වර්ග", "තෙල්, සීනි සහ ලුණු", "මාළු, මස් සහ බිත්තර", "කිරි සහ කිරි නිෂ්පාදන", "ආහාර පිරමිඩයේ පදනම වන්නේ දෛනික ශක්තිය සපයන බත්, කුරක්කන්, පාන් වැනි ධාන්‍ය වර්ගයි."),
        q("ශ්‍රී ලංකා ආහාර පිරමිඩයේ මුදුනේම පිහිටා ඇති, ඉතා අවම වශයෙන් පරිභෝජනය කළ යුතු ආහාර කාණ්ඩය කුමක්ද?", "තෙල්, සීනි සහ ලුණු", "එළවළු සහ පලතුරු", "කිරි සහ කිරි ආශ්‍රිත ආහාර", "පියලි ඇට වර්ග", "තෙල්, ලුණු සහ සීනි අධිකව ගැනීම බෝ නොවන රෝගවලට මඟ පාදන බැවින් අවම කළ යුතුය."),
        q("ආහාර වේලක අඩංගු එළවළු සහ පලතුරුවලින් සිරුරට ප්‍රධාන වශයෙන් ලැබෙන පෝෂ්‍ය පදාර්ථ මොනවාද?", "විටමින්, ඛනිජ ලවණ සහ ආහාරමය තන්තු", "සංතෘප්ත මේදය පමණි", "පළමු පන්තියේ සත්ත්ව ප්‍රෝටීන", "අධික කැලරි ශක්තිය", "එළවළු හා පලතුරු සිරුරේ ආරක්ෂක ආහාර ලෙස ක්‍රියා කරමින් ලෙඩ රෝගවලින් ආරක්ෂා කරයි."),
        q("පැකට් කළ ආහාර සහ බීම වර්ගවල අඩංගු සීනි, ලුණු සහ මේදය පිළිබඳ පාරිභෝගිකයා දැනුවත් කරන වර්ණ සංකේත ක්‍රමය කුමක්ද?", "රථවාහන ආලෝක සංඥා ක්‍රමය (Traffic Light System)", "තීරු කේත ක්‍රමය", "ලේබල් අංක ක්‍රමය", "ISO සහතික ක්‍රමය", "රතු, කහ සහ කොළ වර්ණ මගින් ආහාරයේ අඩංගු සීනි, ලුණු හා මේද මට්ටම සරලව පෙන්වා දෙයි."),
        q("රථවාහන සංඥා වර්ණ ලේබලයක 'රතු' පැහැයෙන් සංකේතවත් කරන්නේ අදාළ සංඝටකයේ කුමන මට්ටමක්ද?", "ඉහළ මට්ටමක පවතින බව (අවම කළ යුතු)", "මධ්‍යම මට්ටමක පවතින බව", "ඉතා අඩු සෞඛ්‍යාරක්ෂිත මට්ටම", "කිසිසේත්ම අඩංගු නොවන බව", "රතු පැහැය මගින් සීනි, ලුණු හෝ මේදය අනතුරුදායක ඉහළ සාන්ද්‍රණයකින් ඇති බව දක්වයි."),
        q("රථවාහන සංඥා වර්ණ ලේබලයක 'කොළ' පැහැයෙන් අදහස් කරන්නේ කුමක්ද?", "අඩු ප්‍රමාණයක් අඩංගු සෞඛ්‍යයට හිතකර බව", "අධික ප්‍රමාණයක් අඩංගු බව", "මධ්‍යම ප්‍රමාණයක් අඩංගු බව", "කල් ඉකුත් වී ඇති බව", "කොළ පැහැය මගින් අදාළ ආහාරයේ සීනි, ලුණු හෝ මේදය අවම සෞඛ්‍ය සම්පන්න මට්ටමක පවතින බව පෙන්වයි."),
        q("එළවළුවල අඩංගු ජලයේ දියවන විටමින් සහ ඛනිජ අපතේ නොයන සේ පිසීමට ගත හැකි සුදුසුම ක්‍රමය කුමක්ද?", "එළවළු කැපීමට පෙර සෝදා වාෂ්පයෙන් තැම්බීම", "එළවළු සිහින්ව කපා දිගු වේලාවක් ජලයේ පොඟවා තැබීම", "අධික තෙලේ ගැඹුරු බැදුම් දැමීම", "විවෘත භාජනයක දමා පැය ගණනක් තැම්බීම", "කැපීමට පෙර සේදීමෙන් හා වාෂ්පයෙන් පිසීමෙන් විටමින් C සහ B සේදී යාම වැළකේ."),
        q("ආහාර පිසීමේදී අධික උෂ්ණත්වයකට තෙල් නැවත නැවත රත් කිරීමෙන් සෑදෙන පිළිකාකාරක අහිතකර මේද වර්ගය කුමක්ද?", "ට්‍රාන්ස් මේදය (Trans Fat)", "ඔමේගා-3 මේදය", "අසංතෘප්ත මේදය", "ස්වාභාවික ලිපිඩ", "නැවත නැවත භාවිත කරන තෙල්වල ට්‍රාන්ස් මේදය සෑදී හෘද රෝග හා පිළිකා අවදානම ඇති කරයි."),
        q("වෙළඳපොළේ ඇති ආහාර කල්තබා ගැනීමට යොදන සෝඩියම් බෙන්සොඒට් සහ සල්ෆර් ඩයොක්සයිඩ් අයත් වන්නේ කුමන කාණ්ඩයටද?", "රසායනික කල්තබා ගැනීමේ ද්‍රව්‍ය (Preservatives)", "ස්වාභාවික රසකාරක", "විටමින් අතිරේක", "ප්‍රෝටීන් සාන්ද්‍රණ", "රසායනික කල්තබා ගැනීමේ ද්‍රව්‍ය මගින් ක්ෂුද්‍රජීවී වර්ධනය පාලනය කර කල්තබා ගනී."),
        q("ආහාරවල රසය වැඩිකිරීම සඳහා බහුලව එක්කරන චීන අහිතකර රසකාරකයක් ලෙස හඳුන්වන සංයෝගය කුමක්ද?", "මොනොසෝඩියම් ග්ලූටමේට් (MSG)", "සෝඩියම් ක්ලෝරයිඩ්", "සිට්‍රික් අම්ලය", "කැල්සියම් කාබනේට්", "MSG අධිකව භාවිත කිරීමෙන් හිසරදය, පපුවේ දැවිල්ල හා ආසාත්මිකතා ඇතිවිය හැක."),
        q("ළමුන් සඳහා කෘත්‍රිම රස, වර්ණ හා අධික සීනි අඩංගු ක්ෂණික පැණිබීම නිතර පානය කිරීමෙන් ඇතිවිය හැකි ප්‍රධාන ගැටලුව කුමක්ද?", "ළමා ස්ථූලතාවය සහ දන්ත ක්ෂය වීම", "බෙරිබෙරි රෝගය", "රිකට්ස් රෝගය", "ස්කර්වි රෝගය", "පැණිබීමවල අඩංගු අනවශ්‍ය කැලරි ප්‍රමාණය නිසා ළමා ස්ථූලතාවය හා දත් දිරායාම සීඝ්‍රයෙන් වැඩිවේ."),
        q("ආහාරයක් බැක්ටීරියා හෝ දිලීර මගින් නරක් නොවී ආරක්ෂා කර ගැනීමට විජලනය (වියළීම) යොදාගන්නේ කුමන හේතුව නිසාද?", "ක්ෂුද්‍රජීවී වර්ධනයට අවශ්‍ය ජලය ඉවත් වන බැවින්", "ආහාරයේ රසය වැඩිවන බැවින්", "විටමින් ප්‍රමාණය ඉහළ යන බැවින්", "ආහාරයේ වර්ණය වෙනස් නොවන බැවින්", "ක්ෂුද්‍රජීවීන්ට ප්‍රජනනය සඳහා තෙතමනය අත්‍යවශ්‍ය වන අතර විජලනයේදී එය අහිමි වේ."),
        q("ආහාරයක් ලුණු දැමීම (Salting) මගින් කල්තබා ගැනීමේදී සිදුවන මූලික විද්‍යාත්මක මූලධර්මය කුමක්ද?", "ආස්‍රැතිය මගින් ක්ෂුද්‍රජීවී සෛලවලින් ජලය ඉවත් වී විනාශ වීම", "ආහාරයේ උෂ්ණත්වය ඉහළ යාම", "ආහාරයේ pH අගය අධික ලෙස ඉහළ යාම", "ඔක්සිජන් ප්‍රමාණය වැඩිවීම", "අධිපීඩක ලවණ පරිසරය නිසා ක්ෂුද්‍රජීවී සෛල ප්ලාස්මොලයිසියට ලක්වී අක්‍රිය වේ."),
        q("ක්ෂීරපායී සතුන්ගේ කිරිවල ඇති ව්‍යාධිජනක ක්ෂුද්‍රජීවීන් විනාශ කිරීම සඳහා යොදාගන්නා සම්මත ක්‍රමය කුමක්ද?", "පැස්ටරීකරණය (Pasteurization)", "විජලනය", "ලුණු දැමීම", "දුම් ගැසීම", "නියමිත උෂ්ණත්වයකට රත් කර වහාම සිසිල් කිරීමෙන් කිරිවල රසය හා ගුණය ආරක්ෂා කර ක්ෂුද්‍රජීවීන් නසයි."),
        q("ශ්‍රී ලංකාවේ පාරිභෝගික අධිකාරිය මගින් ආහාර නිෂ්පාදනවල මුද්‍රණය කිරීම අනිවාර්ය කර ඇති ලේබල් තොරතුරක් නොවන්නේ කුමක්ද?", "නිෂ්පාදන හිමිකරුගේ පෞද්ගලික දේශපාලන මතය", "නිෂ්පාදිත දිනය සහ කල් ඉකුත්වන දිනය", "කාණ්ඩ අංකය (Batch Number)", "අඩංගු අමුද්‍රව්‍ය ලැයිස්තුව", "ආහාර ලේබලයක නිෂ්පාදිත/කල්ඉකුත්වන දිනය, කාණ්ඩ අංකය, අමුද්‍රව්‍ය හා ශුද්ධ බර අනිවාර්ය වේ."),
        q("ආහාරයක් පරිභෝජනයට පෙර එහි 'කල් ඉකුත්වීමේ දිනය' (Expiry Date) පරීක්ෂා කිරීම අත්‍යවශ්‍ය වන්නේ ඇයි?", "ආහාර විෂවීම සහ පෝෂණ ගුණය පිරිහීමෙන් සිදුවන හානි වළක්වා ගැනීමට", "ආහාරයේ මිල අඩුදැයි දැනගැනීමට", "ආහාරය නිපදවූ රට දැනගැනීමට", "ආහාරය පිසින ආකාරය දැනගැනීමට", "කල් ඉකුත් වූ පසු ක්ෂුද්‍රජීවී විෂ ද්‍රව්‍ය සෑදීමේ හා රෝග ඇතිවීමේ බරපතළ අවදානමක් ඇත."),
        q("අමු මස්, මාළු කැපූ කැපුම් පුවරුවේදීම නොපිසූ සලාද එළවළු කැපීමෙන් සිදුවිය හැකි අනතුර කුමක්ද?", "හරස් දූෂණය (Cross-contamination)", "ආහාරයේ රසය වැඩිවීම", "විටමින් ප්‍රමාණය ඉහළ යාම", "ආහාර විජලනය වීම", "අමු මස්වල ඇති සැල්මොනෙල්ලා වැනි බැක්ටීරියා සලාද එළවළු වෙත මාරු වීම හරස් දූෂණයයි."),
        q("ආහාර පිළියෙල කරන්නෙකු අත් සේදීමේදී සබන් යොදා අවම වශයෙන් තත්පර කීයක් අතුල්ලා සේදිය යුතුද?", "තත්පර 20ක් පමණ", "තත්පර 2ක් පමණ", "මිනිත්තු 15ක්", "තත්පර 5ක්", "තත්පර 20ක් පුරා අත්ල, ඇඟිලි කරු හා නියපොතු සබන් ගා සේදීමෙන් විෂබීජ සම්පූර්ණයෙන්ම ඉවත් වේ."),
        q("පාසල් වියේ පසුවන ක්‍රීඩකයෙකුගේ දෛනික ආහාර වේලෙහි සාමාන්‍ය ශිෂ්‍යයෙකුට වඩා වැඩිපුර අඩංගු විය යුතු පෝෂකය කුමක්ද?", "ශක්තිය සපයන කාබෝහයිඩ්‍රේට් සහ ප්‍රෝටීන", "සංතෘප්ත සත්ත්ව මේදය", "කෘත්‍රිම රසකාරක", "අධික ලුණු", "ක්‍රීඩාවේදී විශාල කැලරි ප්‍රමාණයක් වැය වන බැවින් කාබෝහයිඩ්‍රේට් හා පේශි අලුත්වැඩියාවට ප්‍රෝටීන අවශ්‍ය වේ."),
        q("ක්‍රීඩා තරගයකට පැය 2-3කට පෙර ක්‍රීඩකයෙකු ලබාගත යුතු වඩාත් සුදුසු ආහාරය කුමක්ද?", "පහසුවෙන් ජීර්ණය වන කාබෝහයිඩ්‍රේට් බහුල ආහාර වේලක්", "අධික තෙල් සහිත බැදුම් ආහාරයක්", "ප්‍රෝටීන් අධික මස් වර්ග පමණක්", "හිස්බඩ සිටීම", "පහසුවෙන් දිරවන කාබෝහයිඩ්‍රේට් මගින් රුධිර ග්ලූකෝස් හා ග්ලයිකොජන් මට්ටම ඉහළ නංවයි."),
        q("දීර්ඝ ධාවන තරගයකදී හෝ පාපන්දු තරගයකදී විජලනය හා ලවණ ක්ෂය වීම වැළැක්වීමට සුදුසුම පානය කුමක්ද?", "ජලය සහ ඛනිජ ලවණ අඩංගු සමස්ථානික (Isotonic) පානයක්", "අධික සීනි සහිත කාබනේටඩ් පැණිබීම", "උණුසුම් කිරි කෝපි", "ශක්තිජනක ඇල්කොහොල් පානයක්", "සමස්ථානික ක්‍රීඩා පාන මගින් ශරීරයෙන් ඉවත් වූ ජලය හා ඉලෙක්ට්‍රොලයිට ලවණ ක්ෂණිකව ලබා දෙයි."),
        q("මිනිස් සිරුරේ බාහිර හා අභ්‍යන්තර ආසාදනවලට එරෙහිව සටන් කරන ප්‍රතිශක්තිකරණ පද්ධතියේ ප්‍රධාන තැනුම් සංඝටකය කුමක්ද?", "ප්‍රෝටීන (ප්‍රතිදේහ සහ ප්‍රතිශක්ති සෛල)", "සරල සීනි", "සංතෘප්ත මේදය", "සෙලියුලෝස් කෙඳි", "ප්‍රතිදේහ (Antibodies) යනු ආගන්තුක විෂබීජ විනාශ කිරීම සඳහා ප්‍රෝටීනවලින් නිපදවන විශේෂිත අණු වේ."),
        q("කාබෝහයිඩ්‍රේට ජීර්ණය මුඛය තුළදී ආරම්භ කිරීම සඳහා කෙළවල අඩංගු එන්සයිමය කුමක්ද?", "ටයිලින් (ඛේට ඇමයිලේස්)", "පෙප්සින්", "ට්‍රිප්සින්", "ලයිපේස්", "ඛේට ඇමයිලේස් මගින් පිෂ්ඨය මෝල්ටෝස් බවට බිඳහෙළීම මුඛයේදීම ආරම්භ කරයි."),
        q("ආමාශය තුළදී ප්‍රෝටීන ජීර්ණය කිරීම ආරම්භ කරන ආම්ලික මාධ්‍යයේ ක්‍රියාත්මක වන එන්සයිමය කුමක්ද?", "පෙප්සින්", "ටයිලින්", "සුක්‍රේස්", "ලැක්ටේස්", "ආමාශයික යුෂයේ ඇති හයිඩ්‍රොක්ලෝරික් අම්ලය හමුවේ පෙප්සින් එන්සයිමය මගින් ප්‍රෝටීන බිඳහෙළයි."),
        q("කුඩා අන්ත්‍රයේදී ලිපිඩ බිඳහෙළා මේද අම්ල හා ග්ලිසරෝල් බවට පත්කරන ප්‍රධාන එන්සයිමය කුමක්ද?", "ලයිපේස් (Lipase)", "පෙප්සින්", "ඇමයිලේස්", "රෙනින්", "අග්න්‍යාසයික හා ආන්ත්‍රික ලයිපේස් එන්සයිම මගින් මේදය ජීර්ණය කරනු ලබයි."),
        q("අක්මාව මගින් නිපදවන පිත්තාශයේ ගබඩා වන පිත මගින් ආහාර ජීර්ණයේදී ඉටුකරන ප්‍රධාන කාර්යය කුමක්ද?", "මේදය කුඩා බිඳිති බවට පත්කිරීම (එමල්සිභවනය)", "ප්‍රෝටීන සම්පූර්ණයෙන් ජීර්ණය කිරීම", "පිෂ්ඨය ග්ලූකෝස් බවට පත්කිරීම", "විටමින් නිපදවීම", "පිත මගින් මේදය එමල්සිභවනය කර ලයිපේස් එන්සයිමයට ක්‍රියා කිරීමට මතුපිට වර්ගඵලය වැඩි කරයි."),
        q("ජීර්ණය වූ සරල පෝෂක කුඩා අන්ත්‍රයේ බිත්තිය හරහා රුධිරයට අවශෝෂණය කරන විශේෂිත ව්‍යුහය කුමක්ද?", "ආන්ත්‍රික අංගුලිකා (Villi)", "අක්මා සෛල", "ග්‍රහණිය", "ආමාශ බිත්තිය", "අංගුලිකා සහ ක්ෂුද්‍ර අංගුලිකා මගින් පෝෂක අවශෝෂණය සඳහා ඉතා විශාල වර්ගඵලයක් සපයයි."),
        q("අවශෝෂණය නොවූ අජීර්ණ ආහාර කොටස්වලින් ජලය සහ ඛනිජ ලවණ නැවත අවශෝෂණය කරන්නේ කුමන අවයවයෙන්ද?", "මහා අන්ත්‍රය (Large Intestine)", "ආමාශය", "ග්‍රසනිකාව", "අග්න්‍යාශය", "මහා අන්ත්‍රය මගින් අතිරික්ත ජලය අවශෝෂණය කර මළ ද්‍රව්‍ය ඝන තත්ත්වයට පත් කරයි."),
        q("ශ්‍රී ලංකාවේ ප්‍රධාන ආහාරය වන බත් සමග පරිප්පු හෝ වෙනත් පියලි ඇට වර්ගයක් එක්කර ගැනීම පෝෂණීයව වැදගත් වන්නේ ඇයි?", "ධාන්‍ය හා පියලි ඇට එකතු වූ විට සම්පූර්ණ ඇමයිනෝ අම්ල සංකලනයක් ලැබෙන බැවින්", "ආහාරයේ තෙල් ප්‍රමාණය වැඩිවන බැවින්", "පිෂ්ඨය ජීර්ණය වීම ප්‍රමාද වන බැවින්", "ආහාරයේ රසය පමණක් වැඩිවන බැවින්", "ධාන්‍යවල අඩු ඇමයිනෝ අම්ල පියලි ඇටවලින්ද, පියලි ඇටවල අඩු ඇමයිනෝ අම්ල ධාන්‍යවලින්ද එකිනෙක පරිපූරණය වේ."),
        q("වර්ධනය වන නව යොවුන් දරුවෙකුගේ ආහාර වේලෙහි යකඩ සහ ප්‍රෝටීන් විශේෂයෙන් වැදගත් වන්නේ මන්ද?", "ශීඝ්‍ර වර්ධනය, මාංශපේශී ගොඩනැගීම සහ රුධිර පරිමාව වැඩිවීම නිසා", "ශරීරයේ මේදය තැන්පත් කර ගැනීමට", "අස්ථිවල බර අඩු කර ගැනීමට", "නින්ද වැඩි කර ගැනීමට", "නව යොවුන් වියේ ශීඝ්‍ර වර්ධන පිම්ම නිසා මාංශපේශී හා රුධිර නිෂ්පාදනයට ප්‍රෝටීන හා යකඩ අත්‍යවශ්‍ය වේ."),
        q("දිනපතා උදෑසන ආහාර වේල මඟහැරීම නිසා පාසල් සිසුන්ට ඇතිවිය හැකි ක්ෂණික අහිතකර ප්‍රතිඵලය කුමක්ද?", "රුධිර ග්ලූකෝස් මට්ටම පහත වැටී අවධානය හා මතක ශක්තිය දුර්වල වීම", "ශරීරයේ උස එකවර වැඩිවීම", "ශරීරයේ රුධිර පීඩනය අධික ලෙස ඉහළ යාම", "අස්ථි ශක්තිමත් වීම", "උදෑසන ආහාරය මඟහැරීමෙන් මොළයට අවශ්‍ය ග්ලූකෝස් නොලැබී උදාසීන බව හා ක්ලාන්තය ඇතිවේ.")
    )
}
